package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class CharSequenceTranslator_translate_TriageGen1Test {

    /**
     * Mock implementation of CharSequenceTranslator to control the 'consumed' return value.
     */
    private static class TestTranslator extends CharSequenceTranslator {
        private final int consumedValue;
        private final String replacement;

        TestTranslator(int consumedValue, String replacement) {
            this.consumedValue = consumedValue;
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
            if (consumedValue > 0) {
                out.write(replacement);
                return consumedValue;
            }
            return 0;
        }
    }

    @Test(expected = IllegalArgumentException.class)
    public void testTranslate_NullWriter_ThrowsException() throws IOException {
        CharSequenceTranslator translator = new TestTranslator(0, "");
        translator.translate("test", null);
    }

    @Test
    public void testTranslate_NullInput_ReturnsSilently() throws IOException {
        CharSequenceTranslator translator = new TestTranslator(0, "");
        StringWriter out = new StringWriter();
        translator.translate(null, out);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_NoTranslationNeeded() throws IOException {
        CharSequenceTranslator translator = new TestTranslator(0, "");
        StringWriter out = new StringWriter();
        translator.translate("abc", out);
        assertEquals("abc", out.toString());
    }

    @Test
    public void testTranslate_SingleCharTranslation() throws IOException {
        // Translator consumes 1 codepoint and replaces it
        CharSequenceTranslator translator = new TestTranslator(1, "X");
        StringWriter out = new StringWriter();
        translator.translate("abc", out);
        assertEquals("XXX", out.toString());
    }

    @Test
    public void testTranslate_SurrogatePairTranslation_BranchPosLenMinus2() throws IOException {
        // Test case for the 'if (pos < len - 2)' branch logic.
        // Using a surrogate pair (e.g., Emoji 𝄞 U+1D11E)
        // String length is 2, codePointCount is 1.
        String emoji = "\uD834\uDD1E"; 

        // Case 1: Translator handles the surrogate pair (consumed = 1)
        // pos = 0, len = 1. 
        // Inside loop: consumed = 1. 
        // if (pos < len - 2) -> 0 < 1 - 2 is false.
        // else -> pos++
        // pos-- -> pos = 0
        // pos++ -> pos = 1 (loop terminates)
        CharSequenceTranslator translator = new TestTranslator(1, "Y");
        StringWriter out = new StringWriter();
        translator.translate(emoji, out);
        assertEquals("Y", out.toString());
    }

    @Test
    public void testTranslate_SurrogatePairTranslation_BranchPosLessThanLenMinus2() throws IOException {
        // To hit 'pos < len - 2', we need len to be at least 3.
        // Input: [Emoji][Char] -> len=2, codePointCount=2. pos=0. 0 < 2-2 is false.
        // Input: [Char][Emoji] -> len=3, codePointCount=2. pos=0. 0 < 2-2 is false.
        // Input: [Char][Char][Emoji] -> len=4, codePointCount=3. pos=0. 0 < 3-2 is true.

        String input = "a\uD834\uDD1E"; // 'a' (1) + Emoji (1) = 2 codepoints. len=3.
        // pos=0, len=2. 0 < 2-2 is false.

        String input2 = "ab\uD834\uDD1E"; // 'a'(1), 'b'(1), Emoji(1) = 3 codepoints. len=4.
        // pos=0, len=3. 0 < 3-2 is true.

        CharSequenceTranslator translator = new TestTranslator(1, "Z");
        StringWriter out = new StringWriter();
        translator.translate(input2, out);
        // Codepoint 0 ('a') replaced by Z. pos becomes 1.
        // Codepoint 1 ('b') replaced by Z. pos becomes 2.
        // Codepoint 2 (Emoji) replaced by Z. pos becomes 3.
        assertEquals("ZZZ", out.toString());
    }

    @Test
    public void testTranslate_ComplexMixed() throws IOException {
        // Custom translator that only translates 'b'
        CharSequenceTranslator translator = new CharSequenceTranslator() {
            @Override
            public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
                if (input.charAt(index) == 'b') {
                    out.write("B");
                    return 1;
                }
                return 0;
            }
        };
        StringWriter out = new StringWriter();
        translator.translate("a b", out);
        assertEquals("a B", out.toString());
    }
}
